#include "dk1/dynamic_tile_stream.h"
#include <string.h>
static size_t map_address(const Dk1PpuBgLayout*l,size_t x,size_t y){size_t sx=x/32u,sy=y/32u,ix=x%32u,iy=y%32u,screen;if(l->tilemap_width==64u&&l->tilemap_height==64u)screen=sy*2u+sx;else if(l->tilemap_width==64u)screen=sx;else if(l->tilemap_height==64u)screen=sy;else screen=0u;return(size_t)l->screen_base_word+screen*0x400u+iy*32u+ix;}
static bool write_column(const Dk1RomImage*r,const Dk1LevelTerrainConfig*c,const Dk1PpuBgLayout*l,size_t col,Dk1VramImage*v,Dk1DynamicTileStreamStats*s){uint16_t tiles[DK1_LEVEL_MAP_TILES_PER_COLUMN*DK1_LEVEL_MAP_TILE_ROWS];size_t x,y,height=l->tilemap_height<DK1_LEVEL_MAP_TILE_ROWS?l->tilemap_height:DK1_LEVEL_MAP_TILE_ROWS;if(!dk1_level_map_expand_tiles(r,c,col,1u,tiles,4u,64u))return false;for(y=0;y<height;y++)for(x=0;x<4u;x++){size_t tx=(col*4u+x)%l->tilemap_width;size_t wa=map_address(l,tx,y)&0x7FFFu;uint16_t w=tiles[y*4u+x];v->bytes[wa*2u]=(uint8_t)w;v->bytes[wa*2u+1u]=(uint8_t)(w>>8u);s->tile_words++;}s->map_columns++;s->tile_columns+=4u;return true;}
bool dk1_dynamic_tile_stream_apply(const Dk1RomImage*r,const Dk1LevelTerrainConfig*c,const Dk1PpuBgLayout*l,const Dk1DynamicStreamUpdate*u,Dk1VramImage*v,Dk1DynamicTileStreamStats*s){size_t col;if(!r||!c||!l||!u||!v||!s||l->tilemap_width==0u||l->tilemap_height==0u)return false;memset(s,0,sizeof(*s));if(!u->changed)return true;if(u->old_first==u->new_first&&u->columns_entered==(uint16_t)(u->new_last-u->new_first+1u)){for(col=u->new_first;col<=u->new_last;col++)if(!write_column(r,c,l,col,v,s))return false;return true;}if(u->new_first<u->old_first)for(col=u->new_first;col<u->old_first;col++)if(!write_column(r,c,l,col,v,s))return false;if(u->new_last>u->old_last)for(col=(size_t)u->old_last+1u;col<=u->new_last;col++)if(!write_column(r,c,l,col,v,s))return false;return true;}
